/**
 * All for ADHD copy in the nine Guilduo languages. The Japanese text is the key
 * (it is also the source copy), so the UI code stays readable; each row lists
 * en, es, pt-BR, fr, de, ko, zh-Hans, ru. `{name}` placeholders are filled by
 * `tx`. The language is the shared Guilduo choice (`questforge-locale`).
 */

import { getLocale } from "../../i18n.ts";

const ORDER = ["en", "es", "pt-BR", "fr", "de", "ko", "zh-Hans", "ru"] as const;
type Row = readonly [string, string, string, string, string, string, string, string];

export function tx(ja: string, vars: Readonly<Record<string, string | number>> = {}): string {
  const locale = getLocale();
  const index = ORDER.indexOf(locale as (typeof ORDER)[number]);
  const text = index < 0 ? ja : COPY[ja]?.[index] ?? COPY[ja]?.[0] ?? ja;
  return text.replace(/\{(\w+)\}/g, (match, key: string) => (key in vars ? String(vars[key]) : match));
}

